@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + RequestID : string
  + ItemDescription : string
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteID : string
  + Date : date
}

class Article {
  + RFIDTag : string
  + Category : string
  + Description : string
  + Weight : float
  + Dimensions : string
}

class DistributionCenter {
  + Address : string
}

class Employee {
  + EmployeeID : string
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
}

class Category {
  + CategoryName : string
}

H2SLocation "1" -- "1" City
H2SLocation "1" *-- "1" DistributionCenter

Resident "1" -- "0..*" PickupRequest
PickupRequest "1" -- "1" Article

Vehicle "1" -- "0..*" PickupRoute
VolunteerDriver "1" -- "0..*" PickupRoute
PickupRoute "1" -- "1..*" PickupRequest

DistributionCenter "1" -- "1..*" Article
Employee "1" -- "0..*" Article
Article "1" -- "1" Category

Client "1" -- "0..*" Category : requests
Employee "1" -- "0..*" Client : calls
Employee "1" -- "0..*" Article : delivers
VolunteerDriver "1" -- "0..*" Article : delivers

@enduml

